namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough, Tomato sauce, Fresh mozzarella, Basil, Olive oil", Steps = "1. Preheat oven to 475°F\n2. Roll out dough\n3. Spread sauce and add cheese\n4. Bake 10-12 minutes\n5. Top with fresh basil" },
        new Recipe { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti, Pancetta, Eggs, Parmesan, Black pepper", Steps = "1. Cook pasta al dente\n2. Fry pancetta until crispy\n3. Mix eggs with parmesan\n4. Toss hot pasta with pancetta\n5. Stir in egg mixture off heat" },
        new Recipe { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs, Yogurt, Tomato sauce, Cream, Garam masala, Cumin", Steps = "1. Marinate chicken in spiced yogurt\n2. Grill chicken pieces\n3. Simmer tomato sauce with spices\n4. Add cream and grilled chicken\n5. Serve with naan or rice" },
        new Recipe { Id = 4, Title = "Vegetable Biryani", Category = "Indian", Ingredients = "Basmati rice, Mixed vegetables, Saffron, Ghee, Biryani spices, Fried onions", Steps = "1. Parboil rice with whole spices\n2. Cook vegetables with biryani masala\n3. Layer rice and vegetables\n4. Add saffron milk and ghee\n5. Seal and cook on low heat 20 minutes" },
        new Recipe { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef, Taco shells, Lettuce, Tomato, Cheese, Sour cream, Taco seasoning", Steps = "1. Brown beef with taco seasoning\n2. Warm taco shells\n3. Fill with seasoned beef\n4. Top with lettuce, tomato, cheese\n5. Add sour cream and salsa" },
        new Recipe { Id = 6, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados, Lime, Cilantro, Red onion, Jalapeño, Tomato, Salt", Steps = "1. Mash avocados to desired texture\n2. Add lime juice and salt\n3. Fold in diced onion and tomato\n4. Mix in cilantro and jalapeño\n5. Serve immediately with chips" },
        new Recipe { Id = 7, Title = "Pad Thai", Category = "Asian", Ingredients = "Rice noodles, Shrimp, Bean sprouts, Peanuts, Egg, Tamarind sauce, Lime", Steps = "1. Soak rice noodles until soft\n2. Stir-fry shrimp and egg\n3. Add noodles and tamarind sauce\n4. Toss with bean sprouts\n5. Garnish with peanuts and lime" },
        new Recipe { Id = 8, Title = "Miso Ramen", Category = "Asian", Ingredients = "Ramen noodles, Miso paste, Pork broth, Soft-boiled egg, Chashu pork, Green onions, Nori", Steps = "1. Prepare pork broth\n2. Dissolve miso paste into broth\n3. Cook ramen noodles\n4. Assemble bowl with noodles and broth\n5. Top with egg, chashu, nori, and green onions" },
    };

    private readonly Dictionary<int, List<int>> _ratings = new();

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipe(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        if (stars < 1 || stars > 5) return;

        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = new List<int>();

        _ratings[recipeId].Add(stars);

        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe != null)
        {
            recipe.RatingCount = _ratings[recipeId].Count;
            recipe.AverageRating = _ratings[recipeId].Average();
        }
    }

    public void AddRecipe(string title, string category, string ingredients, string steps)
    {
        var newId = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe
        {
            Id = newId,
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps
        });
    }
}

