    }
}

@page "/submit"
@rendermode InteractiveServer

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (Submitted)
{
    <div class="alert alert-success">
        <strong>Thank you!</strong> Your recipe "@Title" has been submitted successfully.
        <a href="/">Back to Home</a>
    </div>
}
else
{
    <EditForm Model="this" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="Title" />
            <ValidationMessage For="() => Title" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="Category">
                <option value="">-- Select a Category --</option>
                <option value="Italian">Italian</option>
                <option value="Indian">Indian</option>
                <option value="Mexican">Mexican</option>
                <option value="Asian">Asian</option>
                <option value="American">American</option>
                <option value="Other">Other</option>
            </InputSelect>
            <ValidationMessage For="() => Category" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (comma-separated)</label>
            <InputTextArea id="ingredients" class="form-control" rows="4" @bind-Value="Ingredients" />
            <ValidationMessage For="() => Ingredients" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="Steps" />
            <ValidationMessage For="() => Steps" />
        </div>

        <button type="submit" class="btn btn-primary">Submit Recipe</button>
    </EditForm>
}

@code {
    [Inject] private RecipeHub.Services.RecipeService RecipeService { get; set; } = default!;

    [Required(ErrorMessage = "Title is required")]
    private string Title { get; set; } = string.Empty;

    [Required(ErrorMessage = "Category is required")]
    private string Category { get; set; } = string.Empty;

    [Required(ErrorMessage = "Ingredients are required")]
    private string Ingredients { get; set; } = string.Empty;

    [Required(ErrorMessage = "Steps are required")]
    private string Steps { get; set; } = string.Empty;

    private bool Submitted;

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(Title) || string.IsNullOrWhiteSpace(Category)
            || string.IsNullOrWhiteSpace(Ingredients) || string.IsNullOrWhiteSpace(Steps))
            return;

        RecipeService.AddRecipe(Title, Category, Ingredients, Steps);
        Submitted = true;
    }
}

