toolArgs.file_text:
@rendermode InteractiveServer

<div class="my-3">
    <span class="me-2">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span role="button" style="cursor:pointer; font-size:1.5rem; color:@(star <= SelectedRating ? "gold" : "#ccc")"
              @onclick="() => Rate(star)">★</span>
    }
    @if (SelectedRating > 0)
    {
        <span class="ms-2 text-muted">You rated @SelectedRating star@(SelectedRating > 1 ? "s" : "")</span>
    }
    @if (AverageRating > 0)
    {
        <span class="ms-3 text-muted">Average: @AverageRating.ToString("F1") (@RatingCount ratings)</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Inject] private RecipeHub.Services.RecipeService RecipeService { get; set; } = default!;

    private int SelectedRating;
    private double AverageRating;
    private int RatingCount;

    protected override void OnInitialized()
    {
        LoadRating();
    }

    private void Rate(int stars)
    {
        SelectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        LoadRating();
    }

    private void LoadRating()
    {
        var recipe = RecipeService.GetRecipe(RecipeId);
        if (recipe != null)
        {
            AverageRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
    }
}

